  Notation LO s B0 m x1 x10 x11 x12 x19 x21 x22 x26 x27 x30 x31 :=
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp (Z_to_bv 64 (DT + 4 + 4 * st + B0)) (Z_to_bv 64 (DT + 4 + 4 * st + B0))
             (Z_to_bv 64 (DT + 35 + 4 * st + B0)) (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10 x11 x12 (Z_to_bv 64 (SY + s))
             (Z_to_bv 64 (DT + 12 + 4 * st + B0)) (Z_to_bv 64 (DT + 4 + 4 * st + 4 * off + B0))
             (Z_to_bv 64 (DT + 4 + 4 * st + 4 * off + B0)) (Z_to_bv 64 (DT + 27 + 4 * st + B0)) (Z_to_bv 64 (4 * L)) x19
             (Z_to_bv 64 (DT + 28 + 4 * st + B0)) x21 x22 (Z_to_bv 64 (DT + 19 + 4 * st + B0)) (Z_to_bv 64 2147450880)
