  Lemma c2eA_outer : forall f s B0 U0 dt m1 mC r (w3 w4 w5 w6 w7 w8 w9 x1 x10 x11 x12 x19 x21 x22 x26 x27 x30 x31 : word),
    fill_for_weight f dt U0 s e tb tl sym1 2 sorted = Ok r -> Z.of_nat f = e - s + 1 -> b <= s < e ->
    4 * U0 = 4 * st + 4 * off + B0 -> 0 <= B0 -> U0 = st + off + (s - b) * L ->
    INV m1 dt -> x2l2frA m1 SPA DT st sym1 ->
